const output = [];
for (const [index, item] of $input.all().entries()) {
  const event = item.json;
  const phoneId = event.metadata?.phone_number_id;
  if (phoneId !== '1526007707255136') continue;
  for (const message of event.messages ?? []) {
    output.push({
      json: { message_id: message.id, from: message.from, phone_number_id: phoneId, text: message.text?.body ?? null },
      pairedItem: { item: index }
    });
  }
}
return output;

